\title{The Golden Ratio is Badly Approximable:\\
A Norm-Form Approach to Diophantine Approximation}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop a self-contained, elementary theory of the Diophantine approximation
properties of the golden ratio $\varphi = (1+\sqrt5)/2$, the prototypical
\emph{badly approximable} number and the extremal case of Hurwitz's theorem.
Avoiding the machinery of continued fractions entirely, we base the analysis on a
single algebraic object: the integer \emph{norm form} $N(p,q) = p^2 - pq - q^2$,
which factors over $\R$ as $(p - q\varphi)(p - q\psi)$, where $\psi =
(1-\sqrt5)/2$ is the algebraic conjugate. Because $5$ is not a perfect square,
$N(p,q)$ never vanishes for $q \geq 1$, hence $|N(p,q)| \geq 1$; this integrality
lower bound, combined with the factorization and the estimate $\sqrt5 < 8/3$,
yields the quantitative badly-approximable bound $|\varphi - p/q| \geq (1/3)/q^2$
for all integers $p$ and $q \geq 1$. We further establish a Binet-type identity
$F_{n+1} - \varphi F_n = \psi^n$ relating the Fibonacci convergents to the
geometric decay of the conjugate, derive the \emph{Fibonacci linear forms}
$F_n\varphi - F_{n+1} = -\psi^n$ that drive a Diophantine irrationality engine to
prove $\varphi$ irrational, and deduce that $\varphi$ is \emph{not a Liouville
number}. All results have been formally verified. We close with three conjectural
generalizations to the metallic ratios $\alpha_m = (m + \sqrt{m^2+4})/2$ and to
the Legendre converse characterizing best approximations as continued-fraction
convergents.
\end{abstract}

\section{Introduction}

\subsection{The approximation hierarchy}

Diophantine approximation studies how closely irrational numbers can be
approximated by rationals, measured against the size of the denominator. The
foundational result is \textbf{Dirichlet's approximation theorem}: for every
irrational $\alpha \in \R$ there exist infinitely many fractions $p/q$ (in lowest
terms, $q \geq 1$) with
\[
\left|\alpha - \frac{p}{q}\right| < \frac{1}{q^2}.
\]
Hurwitz (1891) sharpened the universal constant: there are infinitely many $p/q$
with $|\alpha - p/q| < 1/(\sqrt5\,q^2)$, and $\sqrt5$ is optimal, the unique
obstruction being $\varphi$ and its $\mathrm{GL}_2(\Z)$-equivalents.

A real number $\alpha$ is \textbf{badly approximable} if there is a constant
$c > 0$ with $|\alpha - p/q| \geq c/q^2$ for all rationals $p/q$. Equivalently the
partial quotients of $\alpha$ are bounded. The golden ratio, whose continued
fraction is $[1;1,1,1,\ldots]$, has the smallest possible partial quotients and
is the extremal badly approximable number realizing the Hurwitz wall.

At the opposite end sit the \textbf{Liouville numbers}: irrationals $\alpha$ such
that for every $n$ there exist infinitely many $p/q$ with $|\alpha - p/q| <
1/q^n$. Liouville (1844) proved algebraic numbers cannot be Liouville. Badly
approximable numbers are maximally far from Liouville.

\subsection{Contribution}

We isolate the quantitative core for $\varphi$ through a purely algebraic
argument built on the integer norm form, with no appeal to the general theory of
continued fractions:
\begin{enumerate}
  \item Norm-form factorization (Theorem~\ref{thm:normform}).
  \item Integrality of the norm (Theorem~\ref{thm:nonvanish}, Corollary~\ref{cor:intlb}).
  \item Binet-type identity (Theorem~\ref{thm:binet}).
  \item Fibonacci linear forms (Theorem~\ref{thm:smallforms}).
  \item Irrationality of $\varphi$ (Theorem~\ref{thm:irr}).
  \item Badly approximable bound (Theorem~\ref{thm:badly}).
  \item $\varphi$ not Liouville (Corollary~\ref{cor:liouville}).
\end{enumerate}

\section{Definitions and basic identities}

\begin{definition}
The \emph{golden ratio} and its \emph{conjugate} are
\[
\varphi = \frac{1+\sqrt5}{2}, \qquad \psi = \frac{1-\sqrt5}{2}.
\]
\end{definition}

\begin{lemma}[algebraic relations]\label{lem:rel}
$\varphi + \psi = 1$, \quad $\varphi\,\psi = -1$, \quad $\varphi - \psi = \sqrt5$.
\end{lemma}
\begin{proof}
Direct computation from $(\sqrt5)^2 = 5$; for the product,
$\varphi\psi = \tfrac14(1+\sqrt5)(1-\sqrt5) = \tfrac14(1-5) = -1$.
\end{proof}

\begin{lemma}[quadratic equations]\label{lem:quad}
Both $\varphi$ and $\psi$ satisfy $x^2 = x + 1$.
\end{lemma}
\begin{proof}
$x^2 - x - 1 = (x - \varphi)(x - \psi)$ by Lemma~\ref{lem:rel}.
\end{proof}

\begin{lemma}[size of the conjugate]\label{lem:psisize}
$|\psi| < 1$; explicitly $-1 < \psi < 0$, since $2 < \sqrt5 < 3$.
\end{lemma}

\begin{lemma}[numerical bound]\label{lem:sqrt5}
$\sqrt5 < 8/3$, since $(8/3)^2 = 64/9 > 5$.
\end{lemma}

\section{The norm form and the integrality lower bound}

\begin{theorem}[norm-form factorization]\label{thm:normform}
For all real $p, q$,
\[
(p - q\varphi)(p - q\psi) = p^2 - pq - q^2.
\]
\end{theorem}
\begin{proof}
$(p - q\varphi)(p - q\psi) = p^2 - pq(\varphi+\psi) + q^2\varphi\psi
= p^2 - pq - q^2$ by Lemma~\ref{lem:rel}.
\end{proof}

\begin{theorem}[nonvanishing of the norm]\label{thm:nonvanish}
For integers $p,q$ with $q \geq 1$, $\;p^2 - pq - q^2 \neq 0$.
\end{theorem}
\begin{proof}
If $p^2 - pq - q^2 = 0$, then $(2p-q)^2 = 5q^2$, so $5 = ((2p-q)/q)^2$ is the
square of a rational, hence $5$ is a perfect square in $\Z$. But $4 < 5 < 9$, a
contradiction.
\end{proof}

\begin{corollary}[integrality lower bound]\label{cor:intlb}
For integers $p,q$ with $q \geq 1$, $\;|p^2 - pq - q^2| \geq 1$.
\end{corollary}
\begin{proof}
A nonzero integer (Theorem~\ref{thm:nonvanish}) has absolute value at least $1$.
\end{proof}

\section{Fibonacci convergents and irrationality}

With $F_0 = 0$, $F_1 = 1$, $F_{n+2} = F_{n+1} + F_n$, the convergents of $\varphi$
are $F_{n+1}/F_n$.

\begin{theorem}[Binet-type identity]\label{thm:binet}
For all $n \geq 0$, $\;F_{n+1} - \varphi\,F_n = \psi^{\,n}$.
\end{theorem}
\begin{proof}
Strong induction. Base cases: $n=0$ gives $1 = \psi^0$; $n=1$ gives
$1 - \varphi = \psi$ by Lemma~\ref{lem:rel}. For $n \geq 2$,
\[
F_{n+1} - \varphi F_n = (F_n - \varphi F_{n-1}) + (F_{n-1} - \varphi F_{n-2})
= \psi^{n-1} + \psi^{n-2} = \psi^{n-2}(\psi+1) = \psi^{n-2}\psi^2 = \psi^n,
\]
using the inductive hypothesis and $\psi^2 = \psi + 1$ (Lemma~\ref{lem:quad}).
\end{proof}

Equivalently $F_n\varphi - F_{n+1} = -\psi^n$, nonzero and tending to $0$.

\begin{theorem}[small linear forms]\label{thm:smallforms}
For every $\varepsilon > 0$ there exist $q \geq 1$ and $p \in \Z$ with
$0 < |q\varphi - p| < \varepsilon$.
\end{theorem}
\begin{proof}
Choose $N$ with $|\psi|^{N+1} < \varepsilon$. Set $q = F_{N+1}$, $p = F_{N+2}$.
Then $q\varphi - p = -\psi^{N+1}$ by Theorem~\ref{thm:binet}, so
$|q\varphi - p| = |\psi|^{N+1} < \varepsilon$, nonzero since $\psi \neq 0$.
\end{proof}

\begin{theorem}[irrationality]\label{thm:irr}
$\varphi$ is irrational.
\end{theorem}
\begin{proof}
If $\alpha = a/b$ ($b \geq 1$) then $q\alpha - p = (qa - pb)/b$ has denominator
$b$; if nonzero its absolute value is $\geq 1/b$. Taking $\varepsilon = 1/b$ in
Theorem~\ref{thm:smallforms} yields a contradiction. Hence $\varphi$ is
irrational.
\end{proof}

\section{The badly-approximable bound and its consequences}

\begin{theorem}[badly approximable]\label{thm:badly}
For all integers $p$ and all integers $q \geq 1$,
\[
\left|\varphi - \frac{p}{q}\right| \geq \frac{1/3}{q^2}.
\]
\end{theorem}
\begin{proof}
Set $t = |p - q\varphi|$. By Theorem~\ref{thm:normform} and
Corollary~\ref{cor:intlb},
\[
1 \leq |p^2 - pq - q^2| = |p - q\varphi|\,|p - q\psi| = t\,|p - q\psi|.
\]
Since $p - q\psi = (p - q\varphi) + q\sqrt5$ (Lemma~\ref{lem:rel}),
$|p - q\psi| \leq t + q\sqrt5$, so
\[
1 \leq t(t + q\sqrt5) = t^2 + \sqrt5\,(qt). \tag{$\ast$}
\]
Suppose $qt < 1/3$. As $q \geq 1$, also $t \leq qt < 1/3$, hence $t^2 < 1/9$.
With $\sqrt5 < 8/3$ (Lemma~\ref{lem:sqrt5}),
\[
t^2 + \sqrt5\,(qt) < \tfrac19 + \tfrac83\cdot\tfrac13 = \tfrac19 + \tfrac89 = 1,
\]
contradicting $(\ast)$. So $qt \geq 1/3$, and since $t = q|\varphi - p/q|$,
\[
q^2\left|\varphi - \frac{p}{q}\right| = qt \geq \tfrac13.\qedhere
\]
\end{proof}

\begin{remark}
The constant $1/3$ is not optimal; the sharp constant for $\varphi$ is
$1/\sqrt5 \approx 0.447$, attained in the limit along the Fibonacci convergents.
\end{remark}

\begin{corollary}[not a Liouville number]\label{cor:liouville}
$\varphi$ is not a Liouville number.
\end{corollary}
\begin{proof}
A Liouville number admits, for $n=3$, infinitely many $p/q$ ($q \geq 2$) with
$|\varphi - p/q| < 1/q^3$. But Theorem~\ref{thm:badly} gives $|\varphi - p/q|
\geq (1/3)/q^2$, so $(1/3)/q^2 < 1/q^3$ forces $q < 3$, leaving finitely many
denominators. Hence $\varphi$ is not Liouville. (Equivalently, $\varphi$ is
algebraic of degree $2$, and Liouville's theorem forbids algebraic numbers from
being Liouville.)
\end{proof}

\section{Algorithms}

\paragraph{Fibonacci convergents.}
The best rational approximations $F_{n+1}/F_n$ are generated in linear time by
advancing the Fibonacci pair $(F_i, F_{i+1}) \mapsto (F_{i+1}, F_i + F_{i+1})$.
The error is $|\varphi - F_{n+1}/F_n| = |\psi|^n / F_n$ by Theorem~\ref{thm:binet}.

\paragraph{Verifying the bound.}
For each $q$, the closest fraction has numerator $p = \round(q\varphi)$; the score
$q^2|\varphi - p/q|$ stays $\geq 1/3$ and decreases toward $1/\sqrt5$ along
Fibonacci denominators.

\section{Discussion and future work}

The norm-form method depends only on a real quadratic factorization of an integer
form and the discriminant not being a perfect square, suggesting generalizations.

\begin{conjecture}[metallic ratios are badly approximable]
For each integer $m \geq 1$, the metallic ratio $\alpha_m = (m + \sqrt{m^2+4})/2$
(root of $x^2 = mx + 1$, $\alpha_1 = \varphi$) satisfies $|\alpha_m - p/q| \geq
c_m/q^2$ for all $q \geq 1$, with explicit $c_m = 1/(2\sqrt{m^2+4})$, and is not
Liouville. The norm form $p^2 - mpq - q^2$ factors as $(p - q\alpha_m)(p -
q\beta_m)$ with $\alpha_m - \beta_m = \sqrt{m^2+4}$, and $m^2+4$ is never a
perfect square, so $|N| \geq 1$ exactly as for $\varphi$.
\end{conjecture}

\begin{conjecture}[sharp Hurwitz constant per metallic ratio]
For $\alpha_m$ the optimal Hurwitz constant is exactly $\sqrt{m^2+4}$: for $c >
\sqrt{m^2+4}$ only finitely many $p/q$ satisfy $|\alpha_m - p/q| < 1/(c\,q^2)$,
while infinitely many beat every $c < \sqrt{m^2+4}$.
\end{conjecture}

\begin{conjecture}[Legendre converse]
If $|\alpha - p/q| < 1/(2q^2)$ with $\gcd(p,q)=1$, then $p/q$ is a convergent of
the continued fraction of $\alpha$; the record approximations to a quadratic
irrational are exactly its convergents.
\end{conjecture}

\section{Conclusion}

By distilling the Diophantine behavior of $\varphi$ to a single integer norm form
and the fact that nonzero integers are bounded below by $1$, we obtain a fully
self-contained proof that $\varphi$ is badly approximable, irrational, and not
Liouville, recovering the quantitative essence of Hurwitz's and Liouville's
theorems for the most irrational number without invoking the general theory of
continued fractions.

\end{document}

