function MIN_NONZERO_NORM(q_max):
    best <- +infinity
    for q in 1..q_max:
        for p in 0..2q+1:
            n <- |p^2 - p*q - q^2|
            if n != 0: best <- min(best, n)
    return best        # equals 1

